head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.removeRow(0);
};
scwin.__isDeleted = function() {
	var dataLabel = WebSquare.util.getDataPrefix("label");
    var tree = WebSquare.wUnit.getJq('#treeview1'),
        childOftree = WebSquare.wUnit.getJq(tree).find('div.w2treeview_group'),
        labelAfter = WebSquare.wUnit.getJq('#treeview1_group_1').attr(dataLabel);
    return childOftree.length == 3 && labelAfter != rowLabel;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 0. treeView속성에 forceRefresh='true' 설정한다. 
    //Set forceRefresh = 'true' in the treeView property. 
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('treeview1').setAttribute(scwin.dataForceRefresh, 'true')");
    // verify step 0. treeView속성에 forceRefresh='true' 설정된다. 
    //0. forceRefresh = 'true' is set in the treeView property.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('treeview1').getAttribute(scwin.dataForceRefresh) == 'true'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플파일을 실행 후 'removeRow'버튼을 실행한다.
    //1. Execute the sample file and execute the 'removeRow' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    // Verify step 1. treeView의 즐겨찾기만 삭제되어 보여진다.(이전에는 모두 삭제되어짐. 하위호환이 되지 않음)
    // 1. Only the favorites of the treeView are shown deleted.(Previously all deleted, not backwards compatible)
    WebSquare.wUnit.addCommand("assert", "scwin.__isDeleted()", "true");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Created By: Sang.do
    //Created By: 23-Jan-2018
    var dataLabel = WebSquare.util.getDataPrefix("label");
    window.rowLabel = WebSquare.wUnit.getJq('#treeview1_group_1').attr(dataLabel);
    //end
    scwin.dataForceRefresh = WebSquare.util.getDataPrefix("forceRefresh");
}
